"""Fill text to a width, keeping paragraphs such as "a b\\nc\\n\\nd" -> "a b c\\n\\nd" at width 5."""


def _paragraphs(text):
    """Yield each paragraph as a list of lines; blank or whitespace-only lines separate paragraphs."""
    current = []
    for line in text.splitlines():
        if line.strip():
            current.append(line)
        elif current:
            yield current
            current = []
    if current:
        yield current


def _fill(words, width):
    """Greedily pack words into lines of at most width characters. A word longer than width gets its own line."""
    lines = []
    line = ""
    for word in words:
        if not line:
            line = word
        elif len(line) + 1 + len(word) <= width:
            line += " " + word
        else:
            lines.append(line)
            line = word
    if line:
        lines.append(line)
    return lines


def wrap(text, width):
    """Return text filled to width characters. Paragraphs are separated by one empty line. Raises ValueError if width < 1."""
    if width < 1:
        raise ValueError(f"width must be at least 1: {width}")
    blocks = []
    for lines in _paragraphs(text):
        words = " ".join(lines).split()
        blocks.append("\n".join(_fill(words, width)))
    return "\n\n".join(blocks)

