import contextlib
import io
import unittest

from textkit.cli import main
from textkit.wrap import wrap


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class WrapTest(unittest.TestCase):
    def test_fills_greedily(self):
        self.assertEqual(wrap("aaa bbb ccc", 7), "aaa bbb\nccc")
        self.assertEqual(wrap("aaa bbb ccc", 11), "aaa bbb ccc")

    def test_whitespace_collapses_inside_a_paragraph(self):
        self.assertEqual(wrap("a\n\tb   c\n d", 20), "a b c d")

    def test_paragraphs_keep_one_empty_line(self):
        self.assertEqual(wrap("a b\n\n\n   \nc d", 3), "a b\n\nc d")

    def test_blank_lines_at_edges_are_dropped(self):
        self.assertEqual(wrap("\n  \na b\n\n", 10), "a b")

    def test_empty_text(self):
        self.assertEqual(wrap("", 10), "")
        self.assertEqual(wrap(" \n \n", 10), "")

    def test_long_word_gets_its_own_line(self):
        self.assertEqual(wrap("a extraordinary b", 5), "a\nextraordinary\nb")
        self.assertEqual(wrap("extraordinary", 5), "extraordinary")

    def test_hyphenated_word_is_not_split(self):
        self.assertEqual(wrap("well-known fact", 6), "well-known\nfact")

    def test_width_one(self):
        self.assertEqual(wrap("a bb c", 1), "a\nbb\nc")

    def test_width_below_one_raises(self):
        for width in [0, -3]:
            with self.subTest(width=width), self.assertRaises(ValueError):
                wrap("a b", width)


class WrapCommandTest(unittest.TestCase):
    def test_prints_wrapped_text(self):
        self.assertEqual(run("wrap", "aaa bbb ccc", "--width", "7"), (0, "aaa bbb\nccc\n", ""))

    def test_default_width_is_40(self):
        text = " ".join(["word"] * 12)
        code, out, _ = run("wrap", text)
        self.assertEqual(code, 0)
        self.assertEqual(out, wrap(text, 40) + "\n")
        self.assertTrue(all(len(line) <= 40 for line in out.splitlines()))

    def test_zero_width_is_an_error(self):
        code, out, err = run("wrap", "x", "--width", "0")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error: "))

    def test_listed_in_commands(self):
        _, out, _ = run("commands")
        self.assertIn("wrap", out.split())


if __name__ == "__main__":
    unittest.main()

